Calculate the capacity of cut $C$ in this network.
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont},>=stealth]
\usetikzlibrary{decorations.markings}
\tikzset{midarrow/.style={decoration={markings,mark=at position 0.6 with {\arrow{>}}},postaction={decorate}}}
\definecolor{cutred}{HTML}{EF6068}
\coordinate (S) at (0,0);
\coordinate (A) at (2,1.2);
\coordinate (B) at (2,-1.2);
\coordinate (T) at (4,0);
\draw[midarrow] (S)--(A) node[midway,above left] {$9$};
\draw[midarrow] (S)--(B) node[midway,below left] {$4$};
\draw[midarrow] (A)--(T) node[midway,above right] {$7$};
\draw[midarrow] (B)--(T) node[midway,below right] {$6$};
\draw[dashed,cutred,thick] (0.9,1.7)--(0.9,-1.7);
\path (0.9,1.7) node[above,text=black] {$C$};
\fill (S) circle (2pt) node[left] {$S$};
\fill (A) circle (2pt) node[above] {$A$};
\fill (B) circle (2pt) node[below] {$B$};
\fill (T) circle (2pt) node[right] {$T$};
\end{tikzpicture}
[/tikz]

